import { useEffect, useRef } from 'react'
import gsap from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import TechStackScene from './TechStackScene'
import './MiddleContent.css'

gsap.registerPlugin(ScrollTrigger)


export default function MiddleContentHeader() {
    const pathRef = useRef(null)
    const containerRef = useRef(null)
    const textRef = useRef(null)
    const techSceneRef = useRef(null)

    useEffect(() => {
        const path = pathRef.current
        const container = containerRef.current
        const textElement = textRef.current

        if (!container || !path || !textElement) return

        const pathLength = path.getTotalLength()

        gsap.set(path, {
            strokeDasharray: pathLength,
            strokeDashoffset: pathLength
        })

        gsap.to(path, {
            strokeDashoffset: 1,
            ease: 'none',
            scrollTrigger: {
                trigger: container,
                start: 'top 30%',
                end: 'bottom 38%',
                scrub: 1
            }
        })

        gsap.fromTo(textElement,
            { opacity: 0, x: 100 },
            { 
                opacity: 1,
                x: 0, 
                duration: 1.5, 
                ease: 'power3.out',
                scrollTrigger: {
                    trigger: container,
                    start: 'top 60%',
                    once: true
                }
            }
        )

        if (techSceneRef.current) {
            gsap.fromTo(techSceneRef.current,
                { opacity: 0, y: 50 },
                {
                    opacity: 1,
                    y: 0,
                    duration: 1.2,
                    ease: 'power3.out',
                    scrollTrigger: {
                        trigger: techSceneRef.current,
                        start: 'top 80%',
                        once: true
                    }
                }
            )
        }

        return () => {
            ScrollTrigger.getAll().forEach(trigger => trigger.kill())
        }
    }, [])

    return (
        <>
        <div ref={containerRef} className="middle-content">
            <div className="left-content">
                <svg xmlns="http://www.w3.org/2000/svg" width="1277" height="623" viewBox="0 0 1277 623" version="1.1" fill="none">
	                <path 
                        d="M 422 1.522 C 393.216 7.428, 368.431 27.598, 359.407 52.460 C 349.633 79.387, 359.126 108.702, 385.903 134.285 C 400.147 147.894, 421.216 162.388, 452.325 179.979 L 465.150 187.232 459.825 191.068 C 440.821 204.760, 416.053 214.287, 388.331 218.566 C 373.831 220.804, 344.788 220.824, 327.617 218.608 C 259.566 209.826, 183.577 177.571, 120.792 130.819 C 100.484 115.697, 86.481 103.530, 66.936 84.025 C 46.748 63.879, 32.970 47.850, 17.610 26.638 L 7.721 12.980 4.610 14.950 C 2.900 16.033, 1.500 17.620, 1.500 18.476 C 1.500 19.332, 5.775 25.943, 11 33.167 C 42.992 77.396, 84.942 118.069, 131.331 149.832 C 197.547 195.172, 275.386 224.287, 343.356 229.138 C 389.550 232.436, 433.398 221.258, 465.925 197.893 L 474.350 191.842 489.925 199.331 C 522.331 214.914, 551.824 226.097, 586.500 235.950 C 609.966 242.618, 628.432 246.764, 671.500 255.035 C 730.634 266.391, 758.161 273.319, 784.598 283.500 C 794.715 287.397, 817.574 298.040, 821.793 300.819 C 822.772 301.464, 821.582 304.192, 816.875 312.085 C 807.912 327.119, 795.057 353.318, 788.704 369.500 C 767.953 422.356, 762.669 460.848, 772.302 488.981 C 776.241 500.487, 781.168 508.174, 789.345 515.574 C 815.274 539.039, 860.869 533.415, 889.010 503.282 C 900.583 490.890, 908.309 475.881, 913.241 456.207 C 916.470 443.327, 916.431 416.806, 913.162 402.119 C 908.617 381.698, 900.834 363.953, 889.261 347.628 C 880.997 335.969, 860.625 316.032, 847.303 306.566 L 836.137 298.633 842.079 290.043 C 894.311 214.546, 976.512 153.455, 1064.607 124.663 C 1102.359 112.325, 1136.229 106.414, 1175.500 105.310 C 1207.926 104.399, 1239.639 107.749, 1266.297 114.900 L 1277 117.772 1277 112.995 L 1277 108.219 1268.927 106.041 C 1258.553 103.242, 1244.312 100.490, 1228.805 98.288 C 1211.444 95.823, 1159.180 95.841, 1140.500 98.318 C 1063.948 108.471, 995.597 136.353, 933.229 182.870 C 896.288 210.422, 863.544 244.002, 836.101 282.479 L 828.133 293.650 812.747 286.075 C 778.367 269.148, 748.786 260.623, 675.500 246.521 C 601.398 232.261, 568.836 223.205, 522.188 203.882 C 508.751 198.316, 483.259 186.593, 482.124 185.457 C 481.841 185.174, 484.583 181.919, 488.217 178.222 C 506.129 160, 518.066 135.480, 521.099 110.679 C 523.472 91.277, 519.078 67.927, 509.487 48.965 C 491.794 13.984, 455.961 -5.447, 422 1.522 M 424.500 10.455 C 397.667 15.343, 373.677 35.841, 366.596 59.932 C 364.580 66.792, 364.542 79.777, 366.515 87.540 C 373.701 115.807, 400.047 140.241, 459 173.307 L 472.500 180.880 478.870 174.690 C 502.806 151.430, 515.425 119.118, 512.103 89.594 C 507.547 49.107, 481.481 16.779, 448.266 10.424 C 439.420 8.731, 433.926 8.739, 424.500 10.455 M 825.104 316.196 C 802.291 354.874, 784.094 401.813, 778.469 436.493 C 776.579 448.148, 776.600 469.448, 778.511 478.471 C 781.778 493.891, 791.932 508.487, 803.789 514.807 C 820.471 523.698, 839.599 523.092, 860.533 513.009 C 876.290 505.420, 887.596 494.036, 895.934 477.367 C 906.240 456.761, 909.337 430.619, 904.480 405.233 C 899.247 377.883, 884.587 352.220, 861.748 330.430 C 852.052 321.180, 833.771 307.048, 831.500 307.048 C 830.950 307.048, 828.072 311.164, 825.104 316.196" 
                        ref={pathRef} 
                        stroke="#013ff98f" 
                        strokeWidth="5"
                        strokeLinecap='round'
                        strokeLinejoin='round' 
                        fill="none"/>
                </svg>
            </div>

            <div ref={textRef} className="right-content">
                <h1 className="right-content-title">V.ktr</h1>
                <p className="right-content-caption">Я — начинающий разработчик. Изучаю и применяю современные технологии для создания веб-сайтов, мобильных приложений и автоматизации задач.
                    <p>Работаю с React Native, Next.js, TypeScript, JavaScript, Python, HTML/CSS</p>
                    <p>Интересны реальные проекты, где можно получить опыт и расти как разработчик. Спасибо за внимание! Надеюсь, вам нравится мой сайт!</p>
                </p>
            </div>
        </div>

        <div ref={techSceneRef}>
            <TechStackScene />
        </div>
        </>
    )
}
